// Product inventory helpers — routinely used across the app.

export interface Item {
  sku: string;
  name: string;
  qty: number;
}

export type PriceOf = (sku: string) => number;

export type WantedQuantities = Record<string, number>;

export function stockValue(items: Item[], priceOf: PriceOf): number {
  let total = 0;
  for (const it of items) {
    total += it.qty * priceOf(it.sku);
  }
  return total;
}

export function lowStock(items: Item[], threshold: number = 5): string[] {
  return items
    .filter((it) => it.qty <= threshold)
    .map((it) => it.sku)
    .sort();
}

export function restockReport(items: Item[], wanted: WantedQuantities): string {
  // wanted: { sku -> qty to buy }
  const lines: string[] = [];
  for (const sku of Object.keys(wanted)) {
    const item: Item | undefined = items.find((it) => it.sku === sku);
    const name: string = item ? item.name : "unknown";
    lines.push(`${name}: +${wanted[sku]}`);
  }
  return lines.join("\n");
}

